package com.bank.cash;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class CombinationSumDemo {

    private static final Logger log = Logger.getLogger(CombinationSumDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        NoteCombiner combiner = new NoteCombiner();

        int[] denominations = {2, 3, 5};   // note values
        int target = 8;

        List<List<Integer>> combos = combiner.combinations(denominations, target);
        log.info(() -> "Ways to make " + target + ": " + combos.size());
        combos.forEach(c -> log.info(() -> "  combo: " + c));
    }
}

