class NoteCombiner {

    private static final Logger log = Logger.getLogger(NoteCombiner.class.getName());

    java.util.List<java.util.List<Integer>> combinations(int[] candidates, int target) {
        java.util.Arrays.sort(candidates);   // enables early break prune
        java.util.List<java.util.List<Integer>> result = new java.util.ArrayList<>();
        backtrack(candidates, target, 0, new java.util.ArrayList<>(), result);
        return result;
    }

    private void backtrack(int[] candidates, int remaining, int start,
                           java.util.List<Integer> path,
                           java.util.List<java.util.List<Integer>> result) {
        if (remaining == 0) {                 // exact hit → record a copy
            result.add(new java.util.ArrayList<>(path));
            return;
        }
        for (int i = start; i < candidates.length; i++) {
            if (candidates[i] > remaining) break;  // sorted → no later fits either
            path.add(candidates[i]);
            // reuse allowed: recurse with same index i (not i+1)
            backtrack(candidates, remaining - candidates[i], i, path, result);
            path.remove(path.size() - 1);          // undo
        }
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
